$script:RoboSingleRecipientInvokeExcel = ${function:Invoke-RoboExcel}

function Invoke-RoboExcel {
    param(
        [string]$ExcelPath,
        $Config,
        [hashtable]$StoreMap,
        [string]$ChromePath,
        [string]$ProfilePath
    )

    $testMode = $false
    if ($Config.whatsapp.PSObject.Properties.Name -contains "testMode") {
        $testMode = [bool]$Config.whatsapp.testMode
    }

    $selectedRecipients = @()
    if ($testMode -and ($Config.whatsapp.PSObject.Properties.Name -contains "selectedTestRecipients")) {
        $selectedRecipients = @($Config.whatsapp.selectedTestRecipients)
    }

    if (-not $testMode -or $selectedRecipients.Count -le 1) {
        & $script:RoboSingleRecipientInvokeExcel $ExcelPath $Config $StoreMap $ChromePath $ProfilePath
        return
    }

    $continueOnError = $true
    $retryCount = 1
    $retryDelaySeconds = 3
    $delayBetweenMessages = 4

    if ($Config.whatsapp.PSObject.Properties.Name -contains "continueOnSendError") {
        $continueOnError = [bool]$Config.whatsapp.continueOnSendError
    }
    if ($Config.whatsapp.PSObject.Properties.Name -contains "sendRetryCount") {
        $retryCount = [int]$Config.whatsapp.sendRetryCount
    }
    if ($Config.whatsapp.PSObject.Properties.Name -contains "sendRetryDelaySeconds") {
        $retryDelaySeconds = [int]$Config.whatsapp.sendRetryDelaySeconds
    }
    if ($Config.whatsapp.PSObject.Properties.Name -contains "delayBetweenMessagesSeconds") {
        $delayBetweenMessages = [int]$Config.whatsapp.delayBetweenMessagesSeconds
    }

    $originalPhone = ""
    if ($Config.whatsapp.PSObject.Properties.Name -contains "testPhone") {
        $originalPhone = [string]$Config.whatsapp.testPhone
    }

    $results = New-Object System.Collections.ArrayList
    $total = $selectedRecipients.Count
    $position = 0

    Write-RoboLog ("Inicio do lote de teste com {0} destinatarios." -f $total)

    foreach ($recipient in $selectedRecipients) {
        $position++
        $name = [string]$recipient.name
        if ([string]::IsNullOrWhiteSpace($name)) {
            $name = "Teste $position"
        }
        $phone = ConvertTo-RoboPhone ([string]$recipient.phone)

        if ($phone.Length -lt 10) {
            $message = "Telefone invalido para $name."
            Write-RoboLog $message "ERRO"
            [void]$results.Add([PSCustomObject]@{
                ordem = $position
                nome = $name
                telefone = $phone
                status = "FALHOU"
                tentativas = 0
                erro = $message
                horario = (Get-Date -Format "yyyy-MM-dd HH:mm:ss")
            })
            if (-not $continueOnError) { throw $message }
            continue
        }

        $Config.whatsapp.testPhone = $phone
        $success = $false
        $lastError = ""
        $attempts = 0

        for ($attempt = 1; $attempt -le ($retryCount + 1); $attempt++) {
            $attempts = $attempt
            try {
                Write-RoboLog ("[{0}/{1}] Enviando para {2} | {3} | tentativa {4}" -f $position, $total, $name, $phone, $attempt)
                & $script:RoboSingleRecipientInvokeExcel $ExcelPath $Config $StoreMap $ChromePath $ProfilePath
                $success = $true
                Write-RoboLog ("[{0}/{1}] {2} | {3} | ENVIADO" -f $position, $total, $name, $phone)
                break
            }
            catch {
                $lastError = $_.Exception.Message
                Write-RoboLog ("[{0}/{1}] {2} | {3} | FALHOU tentativa {4}: {5}" -f $position, $total, $name, $phone, $attempt, $lastError) "ERRO"
                if ($attempt -le $retryCount) {
                    Start-Sleep -Seconds $retryDelaySeconds
                }
            }
        }

        $status = if ($success) { "ENVIADO" } else { "FALHOU" }
        [void]$results.Add([PSCustomObject]@{
            ordem = $position
            nome = $name
            telefone = $phone
            status = $status
            tentativas = $attempts
            erro = $lastError
            horario = (Get-Date -Format "yyyy-MM-dd HH:mm:ss")
        })

        if (-not $success -and -not $continueOnError) {
            throw "Falha no envio para $name ($phone): $lastError"
        }

        if ($position -lt $total -and $delayBetweenMessages -gt 0) {
            Start-Sleep -Seconds $delayBetweenMessages
        }
    }

    $Config.whatsapp.testPhone = $originalPhone

    $summaryPath = Join-Path $LogDirectory ("dispatch_summary_{0}.csv" -f (Get-Date -Format "yyyyMMdd_HHmmss"))
    $results | Export-Csv -LiteralPath $summaryPath -NoTypeInformation -Encoding UTF8

    $sent = @($results | Where-Object { $_.status -eq "ENVIADO" }).Count
    $failed = @($results | Where-Object { $_.status -eq "FALHOU" }).Count

    Write-Host ""
    Write-Host "RESUMO DO LOTE DE TESTE" -ForegroundColor Cyan
    Write-Host ("Previstos: {0}" -f $total)
    Write-Host ("Enviados : {0}" -f $sent) -ForegroundColor Green
    Write-Host ("Falhas   : {0}" -f $failed) -ForegroundColor $(if ($failed -gt 0) { "Yellow" } else { "Green" })
    Write-Host ("Resumo CSV: {0}" -f $summaryPath)

    Write-RoboLog ("Fim do lote de teste. Previstos={0}; Enviados={1}; Falhas={2}; Resumo={3}" -f $total, $sent, $failed, $summaryPath)
}

robots/robo-precos/src/network.ps1.content:
function Get-PdaStoreList {
    param([System.Net.WebSockets.ClientWebSocket]$Socket)

    $expression = @'
(() => {
  const norm = s => (s || '').replace(/\s+/g,' ').trim().toLowerCase();
  const selects = [...document.querySelectorAll('select')];
  const center = selects.find(s => [...s.options].some(o =>
    norm(o.textContent).includes('centerlar comercio de utilidades')
  ));

  if (!center) {
    return { ok:false, reason:'center-select-not-found', stores:[] };
  }

  const stores = [];

  for (const option of [...center.options]) {
    const text = (option.textContent || '').replace(/[\r\n\t|]+/g,' ').trim();
    const m = text.match(/^(\d+)-(\d+)\s*-\s*(.+)$/);
    if (!m) continue;

    const a = parseInt(m[1], 10);
    const b = parseInt(m[2], 10);
    if (!Number.isFinite(a) || a <= 0 || a !== b) continue;

    stores.push({
      numero: a,
      loja: 'ML' + String(a).padStart(2,'0'),
      textoPda: text,
      value: option.value
    });
  }

  stores.sort((x,y) => x.numero - y.numero);

  return {
    ok:true,
    count:stores.length,
    stores
  };
})()
'@

    $result = Invoke-CdpJsonExpression -Socket $Socket -Expression $expression

    if ($null -eq $result) {
        throw "O PDA nao retornou a lista de lojas."
    }

    if (-not [bool]$result.ok) {
        throw ("Nao foi possivel listar as lojas do PDA: " + [string]$result.reason)
    }

    $stores = @()

    foreach ($row in @($result.stores)) {
        $number = [int]$row.numero
        if ($number -le 0) { continue }

        $stores += [PSCustomObject]@{
            Numero = $number
            Loja = [string]$row.loja
            TextoPda = [string]$row.textoPda
            ValuePda = [string]$row.value
        }
    }

    if ($stores.Count -eq 0) {
        throw "Nenhuma loja valida foi identificada no dropdown Centro do PDA."
    }

    Write-RoboLog ("Dropdown Centro lido com sucesso: {0} lojas identificadas." -f $stores.Count)

    return @($stores | Sort-Object Numero)
}

function ConvertTo-RoboPrecosDateKey {
    param([Parameter(Mandatory = $true)][string]$DateText)

    $culture = [Globalization.CultureInfo]::InvariantCulture
    $date = [datetime]::ParseExact($DateText, "dd/MM/yyyy", $culture)
    return $date.ToString("yyyyMMdd")
}

function Get-RoboPrecosCollectionPaths {
    param(
        [string]$StartDate,
        [string]$EndDate
    )

    $startKey = ConvertTo-RoboPrecosDateKey $StartDate
    $endKey = ConvertTo-RoboPrecosDateKey $EndDate
    $key = $startKey + "_" + $endKey

    $checkpointDirectory = Join-Path $OutputPath "checkpoints"
    Ensure-RoboDirectory $checkpointDirectory

    return [PSCustomObject]@{
        Key = $key
        Checkpoint = Join-Path $checkpointDirectory ("auditoria_" + $key + ".csv")
        Consolidated = Join-Path $OutputPath ("auditoria_rede_" + $key + ".csv")
    }
}

function New-RoboPrecosRecordMap {
    param(
        [string]$CheckpointPath,
        [string]$StartDate,
        [string]$EndDate
    )

    $map = @{}

    if (-not (Test-Path -LiteralPath $CheckpointPath)) {
        return $map
    }

    try {
        foreach ($row in (Import-Csv -LiteralPath $CheckpointPath)) {
            if ([string]$row.DataInicio -ne $StartDate -or [string]$row.DataFim -ne $EndDate) {
                continue
            }

            $store = ConvertTo-RoboStore $row.Loja
            if ([string]::IsNullOrWhiteSpace($store)) { continue }

            $map[$store] = $row
        }

        Write-RoboLog ("Checkpoint carregado: {0} registros em {1}" -f $map.Count, $CheckpointPath)
    }
    catch {
        Write-RoboLog ("Nao foi possivel ler o checkpoint existente. Um novo sera criado. Detalhe: " + $_.Exception.Message) "AVISO"
        $map = @{}
    }

    return $map
}

function Save-RoboPrecosRecordMap {
    param(
        [hashtable]$Records,
        [string]$Path
    )

    $directory = Split-Path -Parent $Path
    Ensure-RoboDirectory $directory

    $temp = $Path + ".tmp"

    $ordered = @($Records.Values | Sort-Object {
        $n = 999999
        if ([string]$_.Loja -match '(\d+)') { $n = [int]$Matches[1] }
        $n
    })

    $ordered | Export-Csv -LiteralPath $temp -NoTypeInformation -Encoding UTF8
    Move-Item -LiteralPath $temp -Destination $Path -Force
}

function Test-RoboPrecosCompletedRecord {
    param($Record)

    if ($null -eq $Record) { return $false }
    if ([string]$Record.Status -ne "OK") { return $false }

    try {
        $ok = [int]$Record.Ok
        $div = [int]$Record.Divergente
        $sem = [int]$Record.SemEtiqueta
        $total = [int]$Record.Total
        return (($ok + $div + $sem) -eq $total)
    }
    catch {
        return $false
    }
}

function Invoke-RoboPrecosNetworkCollection {
    param(
        [System.Net.WebSockets.ClientWebSocket]$Socket,
        $Config,
        [string]$StartDate,
        [string]$EndDate,
        [int]$RetryPerStore = 3
    )

    $stores = @(Get-PdaStoreList -Socket $Socket)

    if ($stores.Count -lt 2) {
        throw ("Modo rede identificou apenas {0} loja(s). Coleta interrompida para evitar falso sucesso." -f $stores.Count)
    }

    Write-RoboLog ("Modo rede confirmado com {0} lojas. Primeira={1}; Ultima={2}" -f $stores.Count, $stores[0].Loja, $stores[$stores.Count - 1].Loja)

    $paths = Get-RoboPrecosCollectionPaths -StartDate $StartDate -EndDate $EndDate
    $records = New-RoboPrecosRecordMap -CheckpointPath $paths.Checkpoint -StartDate $StartDate -EndDate $EndDate

    Write-Host ""
    Write-Host ("LOJAS IDENTIFICADAS NO PDA: {0}" -f $stores.Count) -ForegroundColor Cyan
    Write-Host ("Periodo: {0} a {1}" -f $StartDate, $EndDate)
    Write-Host ("Checkpoint: {0}" -f $paths.Checkpoint)
    Write-Host ""

    $alreadyDone = 0
    foreach ($store in $stores) {
        if ($records.ContainsKey($store.Loja) -and (Test-RoboPrecosCompletedRecord $records[$store.Loja])) {
            $alreadyDone++
        }
    }

    if ($alreadyDone -gt 0) {
        Write-RoboLog ("Retomada detectada: {0} loja(s) ja concluidas serao preservadas." -f $alreadyDone)
    }

    $position = 0
    foreach ($store in $stores) {
        $position++
        $storeCode = [string]$store.Loja

        if ($records.ContainsKey($storeCode) -and (Test-RoboPrecosCompletedRecord $records[$storeCode])) {
            Write-Host ("[{0}/{1}] {2} - ja concluida, pulando." -f $position, $stores.Count, $storeCode) -ForegroundColor DarkGray
            continue
        }

        Write-Host ""
        Write-Host ("[{0}/{1}] Consultando {2}..." -f $position, $stores.Count, $storeCode) -ForegroundColor Yellow

        $success = $false
        $lastError = ""

        for ($attempt = 1; $attempt -le $RetryPerStore; $attempt++) {
            try {
                if ($attempt -gt 1) {
                    Write-RoboLog ("Nova tentativa {0}/{1} para {2}" -f $attempt, $RetryPerStore, $storeCode) "AVISO"
                    Ensure-PdaAuditPage -Socket $Socket -Config $Config
                }

                $result = Invoke-PdaAuditQuery -Socket $Socket -Config $Config -Store $store.Numero -StartDate $StartDate -EndDate $EndDate

                $records[$storeCode] = [PSCustomObject]@{
                    Loja = $result.Loja
                    NumeroPda = $store.Numero
                    CentroPda = $store.TextoPda
                    DataInicio = $StartDate
                    DataFim = $EndDate
                    Ok = $result.Ok
                    Divergente = $result.Divergente
                    SemEtiqueta = $result.SemEtiqueta
                    Total = $result.Total
                    Status = "OK"
                    Tentativas = $attempt
                    ColetadoEm = $result.ColetadoEm
                    Erro = ""
                }

                Save-RoboPrecosRecordMap -Records $records -Path $paths.Checkpoint
                $success = $true

                Write-Host ("  OK={0} | Divergente={1} | Sem etiqueta={2} | Total={3}" -f $result.Ok, $result.Divergente, $result.SemEtiqueta, $result.Total) -ForegroundColor Green
                break
            }
            catch {
                $lastError = $_.Exception.Message
                Write-RoboLog ("Falha em {0} tentativa {1}/{2}: {3}" -f $storeCode, $attempt, $RetryPerStore, $lastError) "AVISO"

                if ($attempt -lt $RetryPerStore) {
                    Start-Sleep -Seconds 2
                }
            }
        }

        if (-not $success) {
            $records[$storeCode] = [PSCustomObject]@{
                Loja = $storeCode
                NumeroPda = $store.Numero
                CentroPda = $store.TextoPda
                DataInicio = $StartDate
                DataFim = $EndDate
                Ok = ""
                Divergente = ""
                SemEtiqueta = ""
                Total = ""
                Status = "ERRO"
                Tentativas = $RetryPerStore
                ColetadoEm = (Get-Date -Format "yyyy-MM-dd HH:mm:ss")
                Erro = $lastError
            }

            Save-RoboPrecosRecordMap -Records $records -Path $paths.Checkpoint
            Write-Host ("  ERRO apos {0} tentativa(s). Registrado no checkpoint." -f $RetryPerStore) -ForegroundColor Red
        }
    }

    Save-RoboPrecosRecordMap -Records $records -Path $paths.Checkpoint

    $allRows = @($records.Values | Sort-Object {
        $n = 999999
        if ([string]$_.Loja -match '(\d+)') { $n = [int]$Matches[1] }
        $n
    })

    $finalTemp = $paths.Consolidated + ".tmp"
    $allRows | Export-Csv -LiteralPath $finalTemp -NoTypeInformation -Encoding UTF8
    Move-Item -LiteralPath $finalTemp -Destination $paths.Consolidated -Force

    $okRows = @($allRows | Where-Object { [string]$_.Status -eq "OK" })
    $errorRows = @($allRows | Where-Object { [string]$_.Status -eq "ERRO" })

    Write-Host ""
    Write-Host "COLETA DA REDE CONCLUIDA" -ForegroundColor Cyan
    Write-Host ("Lojas identificadas : {0}" -f $stores.Count)
    Write-Host ("Lojas com sucesso   : {0}" -f $okRows.Count) -ForegroundColor Green
    Write-Host ("Lojas com erro      : {0}" -f $errorRows.Count)
    Write-Host ("Arquivo consolidado : {0}" -f $paths.Consolidated)
    Write-Host ("Checkpoint          : {0}" -f $paths.Checkpoint)
    Write-Host ""

    if ($errorRows.Count -gt 0) {
        Write-Host "As lojas com erro nao serao consideradas prontas para preencher a planilha." -ForegroundColor Yellow
        Write-Host "Ao executar novamente o mesmo periodo, o robo preservara as lojas OK e tentara apenas as pendentes." -ForegroundColor Yellow
    }

    return [PSCustomObject]@{
        Stores = $stores
        Rows = $allRows
        SuccessCount = $okRows.Count
        ErrorCount = $errorRows.Count
        CheckpointPath = $paths.Checkpoint
        ConsolidatedPath = $paths.Consolidated
    }
}

robots/robo-precos/src/normalize_input.p.content:
function ConvertTo-RoboNormalizedExcel {
    param(
        [Parameter(Mandatory = $true)][string]$ExcelPath,
        [Parameter(Mandatory = $true)]$Config
    )

    $excel = $null
    $workbook = $null
    $worksheet = $null
    $outWorkbook = $null
    $outWorksheet = $null

    try {
        $excel = New-Object -ComObject Excel.Application
        $excel.Visible = $false
        $excel.DisplayAlerts = $false

        $workbook = $excel.Workbooks.Open($ExcelPath, 0, $true)
        $configuredSheet = [string]$Config.excel.worksheet

        if ([string]::IsNullOrWhiteSpace($configuredSheet)) {
            $worksheet = $workbook.Worksheets.Item(1)
        }
        else {
            $worksheet = $workbook.Worksheets.Item($configuredSheet)
        }

        $used = $worksheet.UsedRange
        $rowCount = [int]$used.Rows.Count
        $columnCount = [int]$used.Columns.Count
        $wanted = ([string]$Config.excel.storeColumn).Trim()
        $aliases = @($wanted, "Loja", "NOME", "Nome")

        $headerRow = 0
        $storeColumn = 0

        $scanRows = [Math]::Min(20, $rowCount)
        for ($row = 1; $row -le $scanRows -and $headerRow -eq 0; $row++) {
            for ($column = 1; $column -le $columnCount; $column++) {
                $text = ([string]$worksheet.Cells.Item($row, $column).Text).Trim()
                foreach ($alias in $aliases) {
                    if (-not [string]::IsNullOrWhiteSpace($alias) -and $text.Equals($alias, [StringComparison]::OrdinalIgnoreCase)) {
                        $headerRow = $row
                        $storeColumn = $column
                        break
                    }
                }
                if ($headerRow -gt 0) { break }
            }
        }

        if ($headerRow -eq 0) {
            throw "Nao foi possivel localizar a coluna de loja nas primeiras 20 linhas do Excel."
        }

        $normalizedPath = Join-Path $OutputPath ("_entrada_normalizada_{0}.xlsx" -f (Get-Date -Format "yyyyMMdd_HHmmssfff"))
        $outWorkbook = $excel.Workbooks.Add()
        $outWorksheet = $outWorkbook.Worksheets.Item(1)

        for ($column = 1; $column -le $columnCount; $column++) {
            $header = ([string]$worksheet.Cells.Item($headerRow, $column).Text).Trim()
            if ($column -eq $storeColumn) {
                $header = $wanted
            }
            if ([string]::IsNullOrWhiteSpace($header)) {
                $header = "Coluna$column"
            }
            $outWorksheet.Cells.Item(1, $column).Value2 = $header
        }

        $destinationRow = 2
        for ($sourceRow = $headerRow + 1; $sourceRow -le $rowCount; $sourceRow++) {
            $rawStore = ([string]$worksheet.Cells.Item($sourceRow, $storeColumn).Text).Trim()
            if ([string]::IsNullOrWhiteSpace($rawStore)) {
                continue
            }

            $normalizedStore = $rawStore.ToUpperInvariant()
            if ($normalizedStore -match '^ML[\s\.\-_]*0*(\d+)') {
                $normalizedStore = "ML{0:D2}" -f [int]$Matches[1]
            }
            elseif ($normalizedStore -match '^\d+([.,]0+)?$') {
                $numberText = $normalizedStore -replace ',', '.'
                $normalizedStore = "ML{0:D2}" -f [int][double]::Parse($numberText, [Globalization.CultureInfo]::InvariantCulture)
            }

            for ($column = 1; $column -le $columnCount; $column++) {
                if ($column -eq $storeColumn) {
                    $outWorksheet.Cells.Item($destinationRow, $column).Value2 = $normalizedStore
                }
                else {
                    $outWorksheet.Cells.Item($destinationRow, $column).Value2 = $worksheet.Cells.Item($sourceRow, $column).Value2
                }
            }
            $destinationRow++
        }

        $outWorkbook.SaveAs($normalizedPath, 51)
        return $normalizedPath
    }
    finally {
        if ($outWorkbook) { try { $outWorkbook.Close($false) } catch {} }
        if ($workbook) { try { $workbook.Close($false) } catch {} }
        if ($excel) { try { $excel.Quit() } catch {} }
        if ($outWorksheet) { try { [void][Runtime.InteropServices.Marshal]::ReleaseComObject($outWorksheet) } catch {} }
        if ($outWorkbook) { try { [void][Runtime.InteropServices.Marshal]::ReleaseComObject($outWorkbook) } catch {} }
        if ($worksheet) { try { [void][Runtime.InteropServices.Marshal]::ReleaseComObject($worksheet) } catch {} }
        if ($workbook) { try { [void][Runtime.InteropServices.Marshal]::ReleaseComObject($workbook) } catch {} }
        if ($excel) { try { [void][Runtime.InteropServices.Marshal]::ReleaseComObject($excel) } catch {} }
        [GC]::Collect()
        [GC]::WaitForPendingFinalizers()
    }
}

$script:RoboBaseInvokeExcel = ${function:Invoke-RoboExcel}

function Invoke-RoboExcel {
    param(
        [string]$ExcelPath,
        $Config,
        [hashtable]$StoreMap,
        [string]$ChromePath,
        [string]$ProfilePath
    )

    $normalizedPath = ConvertTo-RoboNormalizedExcel -ExcelPath $ExcelPath -Config $Config
    Write-RoboLog ("Entrada normalizada para processamento: " + $normalizedPath)

    try {
        & $script:RoboBaseInvokeExcel $normalizedPath $Config $StoreMap $ChromePath $ProfilePath
    }
    finally {
        if ($normalizedPath -and (Test-Path -LiteralPath $normalizedPath)) {
            Remove-Item -LiteralPath $normalizedPath -Force -ErrorAction SilentlyContinue
        }
    }
}

